css='''*{box-sizing:border-box}body{margin:0;background:#09131e;color:#e2eef8;font:16px/1.95 Tahoma,Arial,sans-serif}main{max-width:1180px;margin:auto;padding:28px 20px}h1,h2,h3{line-height:1.65;color:#fff}h1{font-size:clamp(26px,4vw,43px)}a{color:#76dfed}section,.card{background:#122332;border:1px solid #2c475b;border-radius:18px;padding:22px;margin-block:22px}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.stats strong{font-size:32px;display:block;color:#75e3ee}.stats .card{margin:0}code{direction:ltr;unicode-bidi:isolate;overflow-wrap:anywhere;word-break:break-word}.table{max-width:100%;overflow:auto}table{width:100%;border-collapse:collapse}td,th{padding:12px;border:1px solid #355064;text-align:right;vertical-align:top;min-width:130px}th{background:#1b3548}img{display:block;max-width:100%;max-height:900px;object-fit:contain;margin:auto;height:auto}figure{margin:25px 0}figcaption{color:#b5cedf;text-align:center;font-size:.9rem}.note{border-inline-start:4px solid #dfbd70;padding:14px;background:#342f22;border-radius:8px}input,select{font:inherit;padding:12px;background:#09131e;color:#e2eef8;border:1px solid #477087;border-radius:10px;max-width:100%}input{width:100%}summary{cursor:pointer;padding:12px;font-weight:bold}.links{display:flex;flex-wrap:wrap;gap:12px}.links a{padding:10px 14px;border:1px solid #458498;border-radius:10px;text-decoration:none}.filters{display:flex;gap:12px;flex-wrap:wrap;margin-block:20px}.filters input{flex:1;min-width:180px}.muted{color:#a5bed0}@media(max-width:620px){main{padding:18px 12px}.stats{grid-template-columns:1fr}section,.card{padding:16px}.links{display:grid}.filters{display:grid}}@media print{body{background:white;color:#122332}h1,h2,h3{color:#122332}section,.card{background:white;border-color:#aaa}a{color:#124a80}img{max-height:700px}.note{background:#fff4da}}'''
