commits=''.join('<li><code>'+E(line)+'</code></li>' for line in history)
body='''<header><p class="muted">تحویل مرحله تصاویر — ۱۶ اکتبر ۲۰۲۶</p><h1>فروشگاه تهران نتورک</h1><p>فروشگاه در منوی موجود سایت و مسیر /shop قابل مشاهده است. صفحه اصلی آموزش و خدمات حفظ شد. کاتالوگ عمومی در حالت استعلام است؛ انبار، حسابداری و پرداخت واقعی تولید هنوز راه‌اندازی نشده‌اند.</p></header>'''
body+='<div class="links"><a href="https://tehnet.ir/shop/">مشاهده فروشگاه عمومی</a><a href="https://tehnet.ir/wp-admin/admin.php?page=tn-store">ورود به مدیریت فروشگاه</a><a href="store-benchmark-120.html">مقایسه اولیه ۱۲۰ فروشگاه</a><a href="TehNet-store-source.zip">کد و مستندات</a></div>'
body+='<div class="stats"><div class="card"><strong>۲۵</strong>کالای استعلام عمومی با تصویر منبع</div><div class="card"><strong>۳۰</strong>ارجاع تصویر؛ ۲۳ فایل یکتا</div><div class="card"><strong>۰</strong>محصول با مجموعهٔ کامل ۳۶۰ واقعی</div></div>'
body+='<section><h2>تصاویر فعلی روی سایت</h2><p>با تأیید مالکیت و درخواست صریح تازهٔ مالک، نوشتهٔ سعید شبکه از ۱۵ تصویر دارای نوشته پاک شد و نسخه‌های پاک‌سازی‌شده روی ۱۱ محصول قرار گرفتند. ۸ فایل بدون نوشته تغییر نکردند. نشان کم‌رنگ tehnet.ir روی نمایش کارت، گالری و بزرگ‌نمایی باقی است؛ علامت جدید در دانلود مستقیم فایل حک نشده است.</p><p>ابزار داخلی imagegen فقط پس‌زمینهٔ محل نوشته را بازسازی کرد؛ پیکسل‌های اصل بیرون از ماسک بازبینی‌شده دقیقاً حفظ شدند. آزمون مستقل، بازتولید RGB هر ۱۵ نسخه از اصل و وصله و صفر تغییر بیرون ماسک را تأیید کرد. علائم سازنده و جزئیات محصول حفظ شدند؛ اصل فایل‌ها و attachmentهای قبلی برای بازگشت باقی‌اند.</p><p class="note">این‌ها تصاویر کاتالوگ همان منبع‌اند؛ منشأ عکاسی و تطبیق دقیق مدل سازنده تأیید نشده‌اند. روی این کالاها نمای شماتیک قدیمی نمایش داده نمی‌شود. هیچ‌کدام فعلاً مجموعه کامل فریم ۳۶۰ ندارند؛ نمایشگر عکس‌محور آماده است و پس از دریافت و بازبینی فریم‌های واقعی همان مدل فعال می‌شود.</p><p>۳۰ ارجاع تصویر عمومی با رسید جایگزینی تطبیق و URLها با HEAD پاسخ ۲۰۰ دادند؛ شش گروه در گالری، بزرگ‌نمایی و موبایل آزموده شدند. بایت‌های آپلودشده با SHA نسخهٔ بازبینی‌شده برابرند. اجرای دوباره: صفر تغییر و ۲۵ skip. backup تازه با checksum در <code>'+E(cleanup['backup'])+'</code> پیش از تغییر گرفته شد و فیلدهای تجاری/خانه قبل و بعد برابرند.</p><details open><summary>تصاویر واقعی صفحهٔ آنلاین</summary>'+picture('../store-2026-10-16/TN-SN-18002-mobile.png','نمای موبایل محصول پاک‌سازی‌شده با نشان سایت')+picture('../store-2026-10-16/TN-SN-17929-gallery.png','گالری بومی محصول؛ نوشتهٔ فروشنده حذف و برچسب سازنده حفظ شده')+'</details><p>جست‌وجوی SKU فارسی، مقایسه مهمان، فیلتر/reset، مهر فاکتور و صفحات بومی مدیریت حفظ شدند؛ ۱۴ بررسی عمومی تولید دوباره گذشت.</p></section>'
body+='<section><h2>مهر تهران نتورک</h2><p>مهر آبی با نام، حوزه فعالیت و tehnet.ir در پایین فاکتور ERP و اسناد چاپی Core اضافه شد. SVG اندازه ۵۸×۳۶ میلی‌متر و PNG شفاف آماده‌اند. مهر، وضعیت پرداخت یا اعتبار مالیاتی سند را تغییر نمی‌دهد.</p><div class="links"><a href="TehNet-invoice-stamp.svg">مهر برداری SVG</a><a href="TehNet-invoice-stamp.png">مهر PNG شفاف</a></div>'+picture('invoice-stamp.png','مهر اختصاصی تهران نتورک')+'</section>'
body+='<section><h2>مرز آزمون‌های این مرحله</h2><p>قراردادهای مستقل نمایش عکس/فریم، واردسازی و جایگزینی/بازگشت، بازتولید پیکسلی ۱۵ تصویر، lint پنج فایل PHP و syntax جاوااسکریپت گذشتند. '+str(len(photobrowser['checks']))+' بررسی مرورگر تصاویر سایت و ۱۴ بررسی عمومی تولید ثبت شدند. تست توالی ۳۶۰ فقط fixture ساختگی است. ۲۰ قرارداد Python نیز پیش‌تر در همین روز گذشت. ۱۰ گروه کامل Woo/ERP محلی و خرید sandbox در بخش بعد متعلق به ۱۵ اکتبرند. در ۱۶ اکتبر Docker Desktop با خطای WSL بالا نیامد و اجرای تازهٔ آن ۱۰ گروه ادعا نمی‌شود. این مرحله سفارش یا پرداخت واقعی ایجاد نکرد.</p></section>'
body+='<section><h2>آزمون و بازیابی</h2><p>خرید رسمی sandbox با سفارش ساختگی '+str(payment['woo']['order_id'])+'، مبلغ ۳۵۰۰ ریال، وضعیت Woo پردازش، ERP پرداخت‌شده و فاکتور '+E(payment['woo']['invoice'])+' انجام شد؛ تکرار callback همان رسید/فاکتور را حفظ کرد. وجه واقعی جابه‌جا نشد.</p><details><summary>خرید موبایلی آزمایشی</summary>'+picture('payment-checkout-mobile.png','تسویه ساختگی محلی')+picture('payment-receipt-mobile.png','رسید ساختگی Woo و شماره سند ERP')+'</details><p>پشتیبان کامل همان تولید قبل انتشار در DB/volume محلی تازه بازیابی شد؛ همه فایل‌های آرشیو و ۹ جدول داده تطبیق و HTTP 200 تأیید شدند. ایمیل و HTTP خروجی clone بسته بود. پشتیبان روزانه ساعت ۰۳:۴۰ تهران نصب و اجرای واقعی service/checksum تأیید شد.</p><p class="note">یک رویداد مرجوعی محلی HTTP 417 داد؛ همان event پس از خواندن وضعیت، بدون تغییر key تکرار و دو refund با جمع ۲۱۰۰ ریال تطبیق شد. علت پاسخ اولیه معلوم نشد؛ ادعای رفع علت نداریم. شکست و بازیابی هر دو در کد ثبت‌اند؛ اجرای تازه lifecycle و کل بررسی‌ها گذشتند. انتقال backup خارج میزبان و هشدار failure هنوز نیازمند تنظیم‌اند.</p><details><summary>گروه‌های آزمون محلی</summary><div class="table"><table><tr><th>گروه</th><th>نتیجه ثبت‌شدهٔ ۱۵ اکتبر</th></tr>'+groups+'</table></div></details><details><summary>شواهد مرورگر تولید</summary><ul>'+checks+'</ul></details></section>'
body+='<section><h2>وضعیت تک‌تک محصولات</h2><p>قیمت و موجودی منبع برای فروش فعال نشده‌اند. همه این اقلام نیازمند تأیید مدل، قیمت و موجودی واقعی تهران نتورک‌اند؛ صفر بودن stock فروش، اعلام شمارش فیزیکی انبار نیست. عنوان‌های دارای تضاد محافظه‌کارانه شده‌اند؛ نگاشت و داده مرجع حفظ شده است.</p><input id="products-search" aria-label="جست‌وجوی محصولات گزارش" placeholder="نام یا SKU"><div class="table"><table id="products"><thead><tr><th>SKU</th><th>عنوان فعلی</th><th>وضعیت</th><th>مدارک/بررسی باز</th></tr></thead><tbody>'+rows+'</tbody></table></div></section>'
body+='<section><h2>مقایسه فروشگاه‌ها و ادامه اجرا</h2><p>۱۰۰ نمونه خارجی و ۲۰ ایرانی انتخاب شدند؛ '+str(count['public-html-read'])+' HTML عمومی خوانده شد و ۴۱ مورد دسترسی محدود، challenge یا خطای اتصال داشت. این کار رتبه رسمی «۱۰۰/۲۰ سایت برتر» یا آزمون کامل خرید در همه آن‌ها نیست. شواهد و مقایسه اولیه هر دامنه ثبت و ۲۴ مورد اولویت‌بندی شد.</p><p>اولین موارد اجرایی: نمایش عمومی در منوی موجود، رسانه/شماتیک/مهر، سپس جست‌وجوی SKU و جدول مقایسه. موارد وابسته به موجودی، قیمت، سرویس واقعی و مدل مجاز باز هستند.</p><div class="links"><a href="store-benchmark-120.html">جدول تعاملی ۱۲۰ نمونه</a><a href="store-improvement-backlog.fa.md">فهرست اولویت‌ها</a><a href="https://github.com/DashSaman/TehNet/blob/'+head+'/docs/store-improvement-backlog.fa.md">فهرست در مخزن</a></div><p>نمونه‌های مستقیم: <a href="https://store.ui.com/us/en/products/usw-pro-max-16?variant=usw-pro-max-16">Ubiquiti</a>، <a href="https://www.apple.com/shop/buy-iphone">Apple</a>، <a href="https://www.technolife.com/">تکنولایف</a>، <a href="https://netran.net/">نتران</a>؛ چارچوب <a href="https://baymard.com/research-articles/current-state-ecommerce-product-page-ux">Baymard</a>. مقایسه آماری رتبه‌ها از <a href="https://www.similarweb.com/top-websites/e-commerce-and-shopping/">Similarweb</a> فقط زمینه انتخاب است.</p></section>'
body+='<section><h2>کد و اتصال‌های باقی‌مانده</h2><p><a href="https://github.com/DashSaman/TehNet/commit/'+head+'">commit '+E(head[:12])+'</a> — شاخه <code>'+E(branch)+'</code> — انتشار GitHub '+('تأیید شد' if pushed else 'تأیید نشده')+'.</p><ul>'+commits+'</ul><p>برای فروش واقعی هنوز قیمت و موجودی افتتاحیه، ERP روی ظرفیت مناسب، شرکت/مالیات، پذیرنده بانکی، حمل/تعرفه و اعلان واقعی لازم است. درگاه‌ها خاموش، ERP تولید قطع و noindex حفظ شده‌اند. پورت 18082 و سرویس‌های دیگر تغییر نکردند. اسرار، backup و credential داخل این بسته نیستند.</p><p class="muted">GLM فقط یک مشاوره واقعی محدود glm-5.3-flash با ۷۰۷ ورودی + ۵۲۸ خروجی بود؛ اجرای عمده GLM یا تغییر مدل/reasoning مدیر تأیید نشده است. برای benchmark و سپس درخواست مستقل تصاویر، هر بار یک دستیار native Luna فقط نقشه کد همان درخواست را خواند.</p></section>'
script="document.querySelector('#products-search').addEventListener('input',e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('#products tbody tr').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(q))});"
(out/'tehnet-store-report.html').write_text(shell('گزارش فروشگاه تهران نتورک',body,script),encoding='utf-8')
benchbody='<h1>بررسی اولیه ۱۲۰ فروشگاه</h1><p>۱۰۰ خارجی و ۲۰ ایرانی؛ مشاهده HTML عمومی و سرنخ لینک‌ها، نه رتبه رسمی کیفیت یا آزمون خرید کامل. unknown به معنی نبود قابلیت نیست. هیچ چالش ضدربات دور زده نشد.</p><div class="filters"><input id="find" aria-label="جست‌وجوی دامنه یا نام" placeholder="نام یا دامنه"><select id="region" aria-label="منطقه"><option value="">همه مناطق</option><option value="foreign">خارجی</option><option value="iran">ایران</option></select><select id="access" aria-label="وضعیت دسترسی"><option value="">همه وضعیت‌ها</option><option value="public-html-read">HTML خوانده شد</option><option value="access-limited">محدود</option><option value="challenge-page">چالش</option><option value="unavailable">ناموفق</option></select></div><p id="count"></p><div class="table"><table><thead><tr><th>نمونه</th><th>منطقه</th><th>دسترسی</th><th>جست‌وجو در HTML اولیه</th><th>سرنخ سیاست/پشتیبانی</th></tr></thead><tbody id="data"></tbody></table></div><p><a href="tehnet-store-report.html">گزارش فروشگاه</a> · <a href="store-improvement-backlog.fa.md">اولویت‌های اجرا</a></p>'
safe=json.dumps(benchmark['stores'],ensure_ascii=False).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
benchscript='const rows='+safe+''';function render(){const q=document.querySelector('#find').value.toLowerCase(),region=document.querySelector('#region').value,access=document.querySelector('#access').value,list=rows.filter(r=>(r.name+' '+r.domain).toLowerCase().includes(q)&&(!region||r.region===region)&&(!access||r.inspection_status===access));const body=document.querySelector('#data');body.replaceChildren();document.querySelector('#count').textContent=list.length.toLocaleString('fa-IR')+' نمونه';for(const r of list){const tr=document.createElement('tr');for(const text of [r.name,r.region==='iran'?'ایران':'خارجی',r.inspection_status+' / '+(r.http_status||'—'),r.search_input_in_initial_html===true?'input دیده شد':'نامعلوم / مشاهده نشد']){const td=document.createElement('td');td.textContent=text;tr.append(td);}const td=document.createElement('td'),home=document.createElement('a');home.href=r.url;home.textContent=r.domain;td.append(home);for(const [kind,url]of Object.entries(r.candidate_policy_links||{})){if(!url||!url.startsWith('https://'))continue;const a=document.createElement('a');a.href=url;a.textContent=' · '+kind;td.append(a);}tr.append(td);body.append(tr);}}for(const id of ['find','region','access'])document.querySelector('#'+id).addEventListener('input',render);render();'''
